def R(x):
    return f'<span class="raiz">{x}</span>'


def svg_gases():
    return C.svg_orig("3-3_0", {
        "El oxígeno avanza hacia las células": "Oxygen moves toward the cells", "Pulmones": "Lungs", "alvéolos": "alveoli", "Sangre": "Blood",
        "glóbulos rojos": "red blood cells", "Células": "Cells", "mitocondria": "mitochondrion", "El dióxido de carbono regresa": "Carbon dioxide comes back"},
        "Diagram of how gases travel between the lungs and the cells. Oxygen goes from the lungs into the blood and from the blood to the cells, where the mitochondrion uses it. The carbon dioxide made by the cells makes the reverse trip: from the cells to the blood and from the blood to the lungs, where it is breathed out.")


def svg_lazo():
    return C.svg_orig("3-3_1", {
        "Valor de": "Set", "referencia": "point", "1 · Cambio": "1 · Change", "el valor se aparta": "the value moves away", "2 · Receptor": "2 · Receptor",
        "detecta la señal": "detects the signal", "3 · Centro de control": "3 · Control center", "interpreta y ordena": "interprets and gives orders",
        "4 · Efector": "4 · Effector", "ejecuta la orden": "carries out the order", "5 · Respuesta": "5 · Response", "en dirección contraria": "in the opposite direction",
        "al cambio detectado": "to the change detected"},
        "A negative feedback loop in five stages arranged in a circle around the set point. First stage: a change from the set point is detected. Second: a receptor picks up the signal. Third: the control center interprets it and decides. Fourth: an effector carries out the order. Fifth: a response that goes in the opposite direction to the change brings the value back to the set point. The fifth stage connects again with the first, closing the cycle.")


ASMA = [("A", 28), ("B", 41), ("C", 104), ("D", 119)]


def graf_asma():
    sp = {"tipo": "barras", "xEtq": t("Community area", "Área comunitaria"), "yEtq": t("Visits per 10,000 people", "Visitas por cada 10,000 habitantes"), "py": 25,
          "barras": [{"etq": t("Area ", "Área ") + a, "valor": v} for a, v in ASMA]}
    aria = t("Bar graph with illustrative data: emergency room visits for asthma per 10,000 people in four community areas. Area A has 28, area B 41, area C 104, and area D 119. The last two areas have much higher rates than the first two.",
             "Gráfica de barras con datos ilustrativos: visitas a urgencias por asma por cada 10,000 habitantes en cuatro áreas comunitarias. El área A registra 28, el área B 41, el área C 104 y el área D 119. Las dos últimas áreas presentan tasas mucho más altas que las dos primeras.")
    return C.grafica(sp, aria, y0=0, y1=150)


SISTEMAS = [
    (("Circulatory", "Circulatorio"), ("Carries substances all over the body in the blood, pumped by the heart.", "Transporta sustancias por todo el cuerpo mediante la sangre, impulsada por el corazón."), ("Brings it oxygen and nutrients and takes away its wastes.", "Le lleva oxígeno y nutrientes y le retira los desechos."), ("heart, blood vessels, blood", "corazón, vasos sanguíneos, sangre")),
    (("Respiratory", "Respiratorio"), ("Exchanges gases with the air in the alveoli of the lungs.", "Intercambia gases con el aire en los alvéolos pulmonares."), ("Supplies its oxygen and removes the carbon dioxide it makes.", "Le suministra el oxígeno y elimina el dióxido de carbono que produce."), ("lungs, alveoli, windpipe (trachea)", "pulmones, alvéolos, tráquea")),
    (("Digestive", "Digestivo"), ("Breaks food down into molecules the body can absorb.", "Descompone los alimentos hasta moléculas absorbibles."), ("Supplies glucose and other nutrients.", "Le suministra la glucosa y los demás nutrientes.")),
    (("Nervous", "Nervioso"), ("Detects changes, processes the information, and orders fast responses.", "Detecta cambios, procesa la información y ordena respuestas rápidas."), ("Coordinates the work of all the other systems.", "Coordina la actividad de todos los demás sistemas.")),
    (("Immune", "Inmunitario"), ("Finds and neutralizes things foreign to the body.", "Identifica y neutraliza agentes ajenos al organismo."), ("Protects it from infections that would destroy tissue.", "La protege de infecciones que destruirían el tejido.")),
]


