def banco_sistemas():
    nombres = [t(*s[0]) for s in SISTEMAS]
    organos = [
        (t("heart", "corazón"), 0), (t("blood vessels", "vasos sanguíneos"), 0), (t("lungs", "pulmones"), 1), (t("alveoli", "alvéolos"), 1), (t("windpipe (trachea)", "tráquea"), 1),
        (t("stomach", "estómago"), 2), (t("small intestine", "intestino delgado"), 2), (t("brain", "encéfalo"), 3), (t("spinal cord", "médula espinal"), 3), (t("nerves", "nervios"), 3),
        (t("white blood cells", "glóbulos blancos"), 4), (t("antibodies", "anticuerpos"), 4), (t("lymph nodes", "ganglios linfáticos"), 4)]
    P = t("Think about the job: carry, exchange gases, break down food, coordinate, or defend?", "Piense en la función: ¿transportar, intercambiar gases, descomponer el alimento, coordinar o defender?")
    out = []
    for i, s in enumerate(SISTEMAS):
        out.append({"enun": t("Which system does this job?", "¿Qué sistema realiza esta función?") + "<br><strong>" + t(*s[1]) + "</strong>", "ops": nombres, "ok": i, "enOrden": True, "pista": P, "exp": f"<strong>{nombres[i]}.</strong> {t(*s[2])}"})
        out.append({"enun": t("Which system gives the cell this?", "¿Qué sistema aporta esto a la célula?") + "<br><strong>" + t(*s[2]) + "</strong>", "ops": nombres, "ok": i, "enOrden": True, "pista": P, "exp": f"<strong>{nombres[i]}.</strong> {t(*s[1])}"})
    for o, k in organos:
        out.append({"enun": t("Which system does this organ or part belong to?", "¿A qué sistema pertenece este órgano o componente?") + f"<br><strong>{o}</strong>", "ops": nombres, "ok": k, "enOrden": True, "pista": P, "exp": f"<strong>{nombres[k]}.</strong> {t(*SISTEMAS[k][1])}"})
    return out


