def ordenes_lazo():
    def item(tit, pasos, inicio):
        return {"titulo": tit, "intro": t("Put the five parts of the loop in order, from the change to the response. Use ▲ and ▼.", "Ordene las cinco partes del lazo, del cambio a la respuesta. Use ▲ y ▼."), "pasos": pasos, "inicio": inicio,
                "cons": {"1>0": t("The receptor cannot detect a change that has not happened yet.", "El receptor no puede detectar un cambio que aún no ha ocurrido."),
                         "2>1": t("The control center needs the receptor’s signal before it can decide.", "El centro de control necesita la señal del receptor para decidir."),
                         "3>2": t("The effector acts on the control center’s order: the order comes first.", "El efector actúa por orden del centro de control: primero va la orden."),
                         "4>3": t("The response is what the effector produces.", "La respuesta es lo que produce el efector.")},
                "general": t("Change → receptor → control center → effector → response, which brings the value back to the set point.", "Cambio → receptor → centro de control → efector → respuesta, que devuelve el valor a la referencia.")}
    return [
        item(t("Loop 1 · A hot day", "Lazo 1 · Un día de calor"), [t("Change: body temperature rises above 37 °C.", "Cambio: la temperatura corporal sube por encima de 37 °C."), t("Receptor: nerve endings in the skin detect the heat.", "Receptor: las terminaciones nerviosas de la piel detectan el calor."),
              t("Control center: the hypothalamus compares with 37 °C and gives the order.", "Centro de control: el hipotálamo compara con 37 °C y da la orden."), t("Effector: sweat glands make sweat and skin vessels widen.", "Efector: las glándulas producen sudor y los vasos de la piel se dilatan."),
              t("Response: the body loses heat and the temperature goes back down.", "Respuesta: el cuerpo pierde calor y la temperatura vuelve a bajar.")], [3, 0, 4, 2, 1]),
        item(t("Loop 2 · After a meal", "Lazo 2 · Después de comer"), [t("Change: blood glucose rises after a meal.", "Cambio: la glucosa en sangre sube después de comer."), t("Receptor: pancreas cells sense the extra glucose.", "Receptor: las células del páncreas detectan el exceso de glucosa."),
              t("Control center: the pancreas decides to respond.", "Centro de control: el páncreas decide responder."), t("Effector: the pancreas releases insulin.", "Efector: el páncreas libera insulina."),
              t("Response: cells take glucose out of the blood and the level goes back down.", "Respuesta: las células retiran glucosa de la sangre y el nivel vuelve a bajar.")], [4, 2, 0, 3, 1]),
        item(t("Loop 3 · A cold day", "Lazo 3 · Un día de frío"), [t("Change: body temperature drops below 37 °C.", "Cambio: la temperatura corporal baja de 37 °C."), t("Receptor: nerve endings in the skin detect the cold.", "Receptor: las terminaciones nerviosas de la piel detectan el frío."),
              t("Control center: the hypothalamus compares with 37 °C and gives the order.", "Centro de control: el hipotálamo compara con 37 °C y da la orden."), t("Effector: muscles shiver and skin vessels narrow.", "Efector: los músculos tiritan y los vasos de la piel se contraen."),
              t("Response: the body makes and keeps more heat, and the temperature goes back up.", "Respuesta: el cuerpo produce y conserva más calor, y la temperatura vuelve a subir.")], [2, 4, 1, 0, 3]),
    ]


def clasif_retro():
    G = [t("Negative: it reverses the change", "Negativa: revierte el cambio"), t("Positive: it amplifies the change", "Positiva: amplifica el cambio")]
    PN = t("Does the response push the value back toward normal?", "¿La respuesta empuja el valor de vuelta a lo normal?")
    PP = t("Does each step make the change bigger?", "¿Cada paso agranda el cambio?")
    def item(tit, piezas, extra):
        return {"titulo": tit, "intro": t("Decide whether each loop is negative or positive feedback.", "Decida si cada lazo es de retroalimentación negativa o positiva."), "grupos": G,
                "etiqueta": t("Type:", "Tipo:"), "piezas": [{"t": a, "v": v, "pista": [PN, PP][v]} for a, v in piezas], "extra": extra}
    return [
        item(t("Set 1", "Grupo 1"), [
            (t("When you are hot, you sweat and cool down.", "Cuando tiene calor, suda y se enfría."), 0),
            (t("Platelets at a wound attract more platelets, which attract more, until the clot is done.", "Las plaquetas de una herida atraen a más plaquetas, que atraen a más, hasta completar el coágulo."), 1),
            (t("After a meal, insulin lowers blood glucose.", "Después de comer, la insulina baja la glucosa en sangre."), 0),
            (t("During birth, contractions push the baby, which triggers stronger contractions.", "Durante el parto, las contracciones empujan al bebé, lo que provoca contracciones más fuertes."), 1)],
         t("Negative loops end on their own at the set point; positive loops need an outside event (the clot, the birth).", "Los lazos negativos terminan solos en la referencia; los positivos necesitan un suceso externo (el coágulo, el nacimiento).")),
        item(t("Set 2", "Grupo 2"), [
            (t("When you are cold, you shiver and warm up.", "Cuando tiene frío, tirita y entra en calor."), 0),
            (t("Warming melts ice; dark water absorbs more sunlight; that melts more ice.", "El calentamiento derrite el hielo; el agua oscura absorbe más sol; eso derrite más hielo."), 1),
            (t("When you lose water, you feel thirsty and drink.", "Cuando pierde agua, siente sed y bebe."), 0),
            (t("Heat kills part of a forest; the dead trees release carbon; the extra carbon warms the air more.", "El calor mata parte de un bosque; los árboles muertos liberan carbono; ese carbono calienta más el aire."), 1),
            (t("When CO₂ builds up in the blood, you breathe faster and get rid of it.", "Cuando se acumula CO₂ en la sangre, respira más rápido y lo elimina."), 0)],
         t("A vicious circle is a positive loop with nothing to stop it.", "Un círculo vicioso es un lazo positivo sin nada que lo detenga.")),
    ]


